'use client';

import { DollarSign, PackageCheck, ShoppingCart, Star, Users, AlertTriangle } from 'lucide-react';
import { DashboardShell, commonVendorNav } from '@/components/DashboardShell';
import { formatNpr, products } from '@/app/data';
import '../dashboard.css';

export default function VendorDashboard() {
  return <DashboardShell role="vendor" title="Overview" subtitle="Here is how Sajilo Goods is doing this week." nav={commonVendorNav}>
    <div className="dashboard-stat-grid"><Stat label="Store revenue" value="Rs. 184,650" change="↑ 18.4% vs last week" icon={<DollarSign size={15} />} /><Stat label="Orders" value="126" change="↑ 12.8% vs last week" icon={<ShoppingCart size={15} />} /><Stat label="Products live" value="48" change="3 products pending review" icon={<PackageCheck size={15} />} tone="orange" /><Stat label="Store rating" value="4.8 / 5" change="↑ 0.2 this month" icon={<Star size={15} />} /></div>
    <div className="dashboard-chart-grid"><section className="dashboard-panel"><div className="dashboard-panel-header"><div><h2>Revenue overview</h2><p>Your sales performance over the last 30 days</p></div><select className="panel-select" defaultValue="30"><option value="30">Last 30 days</option><option value="7">Last 7 days</option></select></div><RevenueChart /></section><section className="dashboard-panel"><div className="dashboard-panel-header"><div><h2>Orders by status</h2><p>A live view of your fulfilment</p></div></div><div className="donut-wrap"><div className="donut" /><div className="chart-legend"><span><i className="legend-dot" /> Delivered · 46%</span><span><i className="legend-dot two" /> Processing · 26%</span><span><i className="legend-dot three" /> Shipped · 17%</span><span><i className="legend-dot four" /> Other · 11%</span></div></div><div className="dashboard-alert"><span><AlertTriangle size={16} /></span><div><strong>3 products need your attention</strong><p>Low inventory could affect your next orders.</p><a href="#inventory">Review inventory →</a></div></div></section></div>
    <section className="dashboard-panel dashboard-table-panel"><div className="dashboard-panel-header"><div><h2>Recent orders</h2><p>The latest activity from your store</p></div><a className="dashboard-mini-link" href="#orders">View all orders →</a></div><table className="dashboard-table"><thead><tr><th>Order</th><th>Customer</th><th>Date</th><th>Amount</th><th>Status</th></tr></thead><tbody><OrderRow id="#BZ-10482" customer="Aarav Shrestha" date="Today, 10:42 AM" amount="Rs. 5,180" status="Processing" statusClass="orange" /><OrderRow id="#BZ-10477" customer="Maya Gurung" date="Today, 09:18 AM" amount="Rs. 2,890" status="Shipped" statusClass="green" /><OrderRow id="#BZ-10461" customer="Rohan Lama" date="Yesterday" amount="Rs. 8,490" status="Delivered" statusClass="green" /><OrderRow id="#BZ-10455" customer="Pratima K." date="Yesterday" amount="Rs. 1,990" status="Delivered" statusClass="green" /></tbody></table></section>
    <section className="dashboard-panel dashboard-table-panel" id="inventory"><div className="dashboard-panel-header"><div><h2>Inventory pulse</h2><p>Keep your bestsellers ready to ship</p></div><a className="dashboard-mini-link" href="#products">Manage inventory →</a></div><div className="dashboard-metric-list"><Metric image={products[0].image} name={products[0].name} detail="12 units left" percent={22} value="12" /><Metric image={products[2].image} name={products[2].name} detail="27 units left" percent={49} value="27" /><Metric image={products[7].image} name={products[7].name} detail="8 units left" percent={16} value="8" /></div></section>
  </DashboardShell>;
}
function Stat({ label, value, change, icon, tone }: { label: string; value: string; change: string; icon: React.ReactNode; tone?: string }) { return <div className="dashboard-stat-card"><span>{label}</span><strong>{value}</strong><small className={`stat-change ${tone === 'orange' ? 'down' : ''}`}>{change}</small><i className="stat-icon">{icon}</i></div>; }
function RevenueChart() { return <div className="fake-chart"><div className="chart-lines"><span /><span /><span /><span /><span /></div><div className="chart-y-labels"><span>25k</span><span>20k</span><span>15k</span><span>10k</span><span>0</span></div><svg className="chart-svg" viewBox="0 0 700 160" preserveAspectRatio="none"><defs><linearGradient id="fillRevenue" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#e9623d" stopOpacity=".23" /><stop offset="1" stopColor="#e9623d" stopOpacity="0" /></linearGradient></defs><path d="M0 135 C40 126 57 111 90 119 S145 85 180 102 S230 116 260 87 S311 106 345 76 S393 93 425 63 S477 75 510 54 S557 75 590 42 S643 53 700 24 V160 H0 Z" fill="url(#fillRevenue)" /><path d="M0 135 C40 126 57 111 90 119 S145 85 180 102 S230 116 260 87 S311 106 345 76 S393 93 425 63 S477 75 510 54 S557 75 590 42 S643 53 700 24" fill="none" stroke="#e9623d" strokeWidth="2.5" /></svg><div className="chart-x-labels"><span>01 Sep</span><span>07 Sep</span><span>14 Sep</span><span>21 Sep</span><span>Today</span></div></div>; }
function OrderRow({ id, customer, date, amount, status, statusClass }: { id: string; customer: string; date: string; amount: string; status: string; statusClass: string }) { return <tr><td className="table-product"><span className="table-thumb" style={{ background: '#e5eee8' }} /><strong>{id}</strong></td><td>{customer}</td><td>{date}</td><td>{amount}</td><td><span className={`status-pill ${statusClass}`}>{status}</span></td></tr>; }
function Metric({ image, name, detail, percent, value }: { image: string; name: string; detail: string; percent: number; value: string }) { return <div className="dashboard-metric"><img src={image} alt="" className="table-thumb" /><div><strong>{name}</strong><div className="dashboard-progress"><span style={{ width: `${percent}%` }} /></div><small>{detail}</small></div><b>{value}</b></div>; }
